def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 500:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        return max(0.0, min(budget, 15.0))

    slots = max(1, int(supply // WATER_REQ))
    pressure = len(alive_opponents) + 1 - slots
    tight_supply = supply <= 18

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(95.0, highest_prev + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(82.0, avg_prev * 0.9)
        else:
            bid = max(68.0, avg_prev * 0.72)
    else:
        if pressure >= 3 or tight_supply:
            if highest_prev >= 120:
                bid = 24.0
            elif highest_prev >= 90:
                bid = 36.0
            else:
                bid = max(42.0, highest_prev * 0.5)
        else:
            if highest_prev >= 120:
                bid = 18.0
            elif highest_prev >= 90:
                bid = 28.0
            else:
                bid = max(26.0, avg_prev * 0.4 if avg_prev > 0 else 26.0)

    if rich_opp >= 2 and hp > 4 and no_water_days == 0:
        bid *= 0.9
    if urgent_opp >= 2 and (hp <= 4 or no_water_days >= 1):
        bid *= 1.12

    if day >= 8:
        if hp <= 5 or no_water_days >= 1:
            bid *= 1.18
        else:
            bid *= 0.95

    min_survival = 8.0 if hp > 4 and no_water_days == 0 else 20.0
    bid = max(min_survival, bid)
    bid = min(budget, bid)
    if budget < 25:
        bid = budget
    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    # supply is float; convert for any indexing/threshold logic
    supply_int = int(supply)

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            yesterday_bids.append(float(bid))

    # Estimate contest intensity
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base willingness depends on supply: lower supply -> slightly higher bid
    # supply_int in [15,25]
    if supply_int <= 16:
        supply_pressure = 1.0
    elif supply_int <= 19:
        supply_pressure = 0.9
    elif supply_int <= 22:
        supply_pressure = 0.8
    else:
        supply_pressure = 0.7

    # If someone was extremely aggressive yesterday, don't mirror fully; undercut slightly.
    aggressive_threshold = DAILY_SALARY * 0.85  # 76.5

    # If our HP is low, we must secure water.
    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    # Target bid logic
    if highest_prev_bid >= aggressive_threshold:
        # Underbid relative to their peak to win at lower cost.
        target = min(DAILY_SALARY * 0.95, highest_prev_bid * 0.92)
        # If our HP is critical, increase a bit
        if hp <= 2:
            target = min(DAILY_SALARY * 1.0, target + 8.0)
    else:
        # Moderate contest: bid around mid-high of salary scaled by supply pressure.
        target = DAILY_SALARY * 0.62 * supply_pressure
        if hp <= 3:
            target = DAILY_SALARY * 0.78 * supply_pressure

    # Ensure we don't overspend beyond budget
    # Also keep a floor to avoid losing when others spend heavily.
    floor_bid = DAILY_SALARY * 0.5
    if target < floor_bid and hp > 4:
        target = floor_bid * 0.9

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], avg_prev_bid * 1.1)

    if supply < 18:
        return min(my_status['budget'], avg_prev_bid * 1.05)

    return min(my_status['budget'], max(20.0, avg_prev_bid * 0.6))
